import { execFileSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, symlinkSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { expect, it } from 'vitest';

/**
 * R11 extension: the router tree is generated by the official TanStack Router Vite
 * plugin during the normal build, not by a repo-local CLI. Its physical location
 * (app/router/routeTree.gen.ts) is the toolchain contract, so it is deliberately
 * NOT registered in tools/generated-artifacts.json (that registry owns repo-CLI
 * outputs under src/generated). Reproducibility is proven here instead: the
 * official plugin runs in an isolated clean worktree and the committed file must
 * be byte-identical. A stale or hand-edited tree fails; nothing is auto-overwritten.
 */

const webAppRoot = resolve(fileURLToPath(new URL('../../', import.meta.url)));
const repoRoot = resolve(webAppRoot, '..');
const routeTreeRelative = 'src/app/router/routeTree.gen.ts';
const routeTreePath = join(webAppRoot, routeTreeRelative);

function run(command: string, args: string[], options: { cwd: string; timeout?: number }): string {
  return execFileSync(command, args, {
    cwd: options.cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
    timeout: options.timeout ?? 60_000,
  });
}

function isDirectory(file: string): boolean {
  try {
    return statSync(file).isDirectory();
  } catch {
    return false;
  }
}

/** First differing line/byte offset, so a failure names the exact stale region. */
function describeMismatch(generated: Buffer, committed: Buffer): string {
  const generatedLines = generated.toString('utf8').split('\n');
  const committedLines = committed.toString('utf8').split('\n');
  for (let index = 0; index < Math.max(generatedLines.length, committedLines.length); index += 1) {
    if (generatedLines[index] !== committedLines[index]) {
      return [
        routeTreeRelative + ' does not match a fresh official generation at line ' + (index + 1) + '.',
        'generated: ' + JSON.stringify(generatedLines[index] ?? '<missing>'),
        'committed: ' + JSON.stringify(committedLines[index] ?? '<missing>'),
        'Regenerate with the TanStack Router Vite plugin (vite build) and commit the tree; never hand-edit it.',
      ].join('\n');
    }
  }
  return routeTreeRelative + ' differs in byte content but not in lines (check the trailing bytes).';
}

function sourceFiles(directory: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(directory)) {
    const absolute = join(directory, entry);
    if (isDirectory(absolute)) out.push(...sourceFiles(absolute));
    else if (/\.(?:ts|tsx)$/.test(entry)) out.push(absolute);
  }
  return out;
}

it('re-runs the official route generation in a clean worktree and requires byte-identical committed output', () => {
  const probeRoot = mkdtempSync(join(tmpdir(), 'sfn-route-tree-'));
  const probeWebApp = join(probeRoot, 'web_app');
  const nodeModulesLink = join(probeWebApp, 'node_modules');
  try {
    // 1. Isolated, clean worktree of the committed tree (no local edits leak in).
    run('git', ['worktree', 'add', '--detach', probeRoot, 'HEAD'], { cwd: repoRoot, timeout: 120_000 });
    // 2. Reuse the pinned dependency tree instead of installing inside the gate.
    symlinkSync(join(webAppRoot, 'node_modules'), nodeModulesLink, process.platform === 'win32' ? 'junction' : 'dir');
    // 3. Run the official flow (Vite + @tanstack/router-plugin); it regenerates the
    //    route tree in the probe worktree only, so the committed file is never at risk.
    run(process.execPath, [join(webAppRoot, 'node_modules', 'vite', 'bin', 'vite.js'), 'build', '--logLevel', 'error'], {
      cwd: probeWebApp,
      timeout: 180_000,
    });
    // 4. Byte-for-byte comparison against the committed artifact.
    const generated = readFileSync(join(probeWebApp, routeTreeRelative));
    const committed = readFileSync(routeTreePath);
    expect(Buffer.compare(generated, committed), describeMismatch(generated, committed)).toBe(0);
  } finally {
    try {
      if (existsSync(nodeModulesLink)) {
        if (process.platform === 'win32') execFileSync('cmd.exe', ['/c', 'rmdir', nodeModulesLink], { stdio: 'ignore' });
        else rmSync(nodeModulesLink, { recursive: false });
      }
    } catch {
      /* Best-effort link removal; the temp tree removal below still runs. */
    }
    try {
      run('git', ['worktree', 'remove', '--force', probeRoot], { cwd: repoRoot });
    } catch {
      /* A failed removal must not hide the assertion result. */
    }
    rmSync(probeRoot, { recursive: true, force: true });
  }
}, 240_000);

it('pins the router plugin/generator versions and keeps @ts-nocheck scoped to the verified generated file', () => {
  const packageJson = JSON.parse(readFileSync(join(webAppRoot, 'package.json'), 'utf8')) as {
    dependencies?: Record<string, string>;
    devDependencies?: Record<string, string>;
  };
  const pin = (name: string): string => {
    const specifier = packageJson.dependencies?.[name] ?? packageJson.devDependencies?.[name];
    expect(specifier, name + ' must be an exact version pin, never a range').toMatch(/^\d+\.\d+\.\d+$/);
    const installed = JSON.parse(readFileSync(join(webAppRoot, 'node_modules', name, 'package.json'), 'utf8')) as { version: string };
    expect(installed.version, name + ' installed version must equal the pinned version').toBe(specifier);
    return specifier as string;
  };
  const pluginVersion = pin('@tanstack/router-plugin');
  pin('@tanstack/react-router');

  const lockfile = readFileSync(join(webAppRoot, 'pnpm-lock.yaml'), 'utf8');
  expect(lockfile, 'the lockfile importer entry must carry the pinned plugin version').toContain(
    "'@tanstack/router-plugin':\n        specifier: " + pluginVersion,
  );
  // The official plugin transitively pins its generator; exactly one generator
  // resolution in the lockfile keeps the generated output reproducible.
  const generatorVersions = new Set(
    [...lockfile.matchAll(/@tanstack\/router-generator@([0-9][0-9.]*)/g)].map((match) => match[1]),
  );
  expect([...generatorVersions], 'exactly one transitive router-generator version').toHaveLength(1);

  // The generated-file exceptions (@ts-nocheck) must stay confined to this artifact.
  const sourceRoot = join(webAppRoot, 'src');
  const tsNoCheckFiles = sourceFiles(sourceRoot)
    .filter((file) => readFileSync(file, 'utf8').includes('@ts-nocheck'))
    .map((file) => relative(sourceRoot, file).replaceAll('\\', '/'))
    .sort();
  expect(tsNoCheckFiles).toEqual(['app/router/routeTree.gen.ts']);

  const committed = readFileSync(routeTreePath, 'utf8');
  expect(committed).toContain('automatically generated by TanStack Router');
  expect(committed).toContain('@ts-nocheck');
  expect(committed).toContain('You should NOT make any changes in this file');
});
